// Visual (not true-to-scale) half-width for a site's AOI square on the map,
// scaled by hectares so bigger blocks read as bigger shapes.
const luasList = SITES.map((s) => s.luas);
const luasMin = Math.min(...luasList);
const luasMax = Math.max(...luasList);
function aoiHalfWidth(luas) {
  const t = (luas - luasMin) / (luasMax - luasMin || 1);
  return 4.5 + t * 6.5;
}

// simple deterministic square, slightly rotated for a hand-drawn shapefile feel
function squarePoints(cx, cy, hw, rotDeg) {
  const rot = (rotDeg * Math.PI) / 180;
  const corners = [
    [-hw, -hw],
    [hw, -hw],
    [hw, hw],
    [-hw, hw],
  ];
  return corners
    .map(([x, y]) => {
      const rx = x * Math.cos(rot) - y * Math.sin(rot);
      const ry = x * Math.sin(rot) + y * Math.cos(rot);
      return `${(cx + rx).toFixed(1)},${(cy + ry).toFixed(1)}`;
    })
    .join(" ");
}

