function StatusBadge({ status }) {
  const meta = STATUS_META[status];
  const Icon = meta.icon;
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        fontSize: 12.5,
        fontFamily: "'IBM Plex Sans', sans-serif",
        color: meta.color,
      }}
    >
      <Icon size={13} strokeWidth={2.2} />
      {status}
    </span>
  );
}

function KpiStrip({ sites }) {
  const totalLuas = sites.reduce((a, s) => a + s.luas, 0);
  const totalPck = sites.reduce((a, s) => a + s.pck, 0);
  const verified = sites.filter((s) => s.status === "Terverifikasi").length;
  const flagged = sites.filter((s) => s.status !== "Terverifikasi").length;

  const items = [
    { label: "Lokasi kegiatan", value: sites.length, unit: "lokasi" },
    { label: "Luas total", value: fmt(totalLuas), unit: "hektare" },
    { label: "Cadangan karbon", value: fmt(totalPck), unit: "tCO\u2082e" },
    { label: "Terverifikasi", value: verified, unit: `dari ${sites.length}` },
    { label: "Perlu tindak lanjut", value: flagged, unit: "lokasi", warn: flagged > 0 },
  ];

  return (
    <div style={{ display: "flex", flexWrap: "wrap", borderTop: "1px solid #D6D2C4", borderBottom: "1px solid #D6D2C4" }}>
      {items.map((it, i) => (
        <div key={it.label} style={{ flex: "1 1 160px", padding: "16px 22px", borderLeft: i === 0 ? "none" : "1px solid #D6D2C4" }}>
          <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12.5, color: "#5C5A4E", marginBottom: 4 }}>{it.label}</div>
          <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontWeight: 600, fontSize: 26, color: it.warn ? "#A23B3B" : "#1B2A22", lineHeight: 1.1 }}>
            {it.value}
            <span style={{ fontSize: 13, fontWeight: 400, color: "#5C5A4E", marginLeft: 6 }}>{it.unit}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

function Field({ label, value }) {
  return (
    <div>
      <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 11.5, color: "#8A8677", marginBottom: 2 }}>{label}</div>
      <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 14, color: "#1B2A22", fontWeight: 500 }}>{value}</div>
    </div>
  );
}

function Note({ children, tone }) {
  const colors = { danger: "#A23B3B", warn: "#B9791F", neutral: "#5C5A4E" };
  return (
    <div style={{ marginTop: 16, paddingTop: 14, borderTop: "1px solid #D6D2C4", fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12.5, lineHeight: 1.55, color: colors[tone] }}>
      {children}
    </div>
  );
}

// --- Leader-line callout, reused by the mechanism diagrams below -----------
function Callout({ x, y, dotX, dotY, text, tone = "neutral", align = "left" }) {
  const bg = tone === "danger" ? "#A23B3B" : "#EDEAD9";
  const fg = tone === "danger" ? "#F5F3EA" : "#1B2A22";
  const w = text.length * 5.6 + 16;
  const boxX = align === "left" ? x : x - w;
  return (
    <g>
      <line x1={dotX} y1={dotY} x2={x} y2={y} stroke={tone === "danger" ? "#A23B3B" : "#8A8677"} strokeWidth="1" />
      <circle cx={dotX} cy={dotY} r="2.6" fill="none" stroke={tone === "danger" ? "#A23B3B" : "#8A8677"} strokeWidth="1" />
      <rect x={boxX} y={y - 10} width={w} height={20} fill={bg} />
      <text x={boxX + w / 2} y={y + 4} textAnchor="middle" fontFamily="IBM Plex Sans" fontSize="10.5" fontWeight="500" fill={fg}>
        {text}
      </text>
    </g>
  );
}

// Compact recreation of the guideline's "Mekanisme Overlapping RO" diagram
// (Bab III, Gambar 3.2), substituting in the selected site's real IP/name.
function OverlapMechanismDiagram({ site }) {
  return (
    <svg viewBox="0 0 320 220" style={{ width: "100%", height: "auto", display: "block" }}>
      <defs>
        <pattern id="hatchOverlap" patternUnits="userSpaceOnUse" width="6" height="6" patternTransform="rotate(45)">
          <rect width="6" height="6" fill="#E7C9D6" />
          <line x1="0" y1="0" x2="0" y2="6" stroke="#A23B3B" strokeWidth="1.6" />
        </pattern>
      </defs>
      <rect x="0" y="0" width="320" height="220" fill="#3C4A34" />
      <rect x="0" y="0" width="320" height="220" fill="#000" opacity="0.08" />

      {/* AOI kegiatan situs terpilih */}
      <rect x="70" y="60" width="90" height="90" fill="url(#hatchOverlap)" stroke="#D9B23C" strokeWidth="2" strokeDasharray="6 4" />
      {/* AOI IP tetangga, overlap sebagian */}
      <rect x="120" y="40" width="90" height="70" fill="none" stroke="#D9B23C" strokeWidth="2" strokeDasharray="6 4" />

      <Callout x={20} y={30} dotX={95} dotY={72} text={`AOI ${site.ip}`} />
      <Callout x={190} y={20} dotX={165} dotY={55} text={`AOI ${site.overlapIp || "IP lain"}`} align="left" />
      <Callout x={110} y={190} dotX={120} dotY={112} text="Overlapping" tone="danger" />
    </svg>
  );
}

// Compact recreation for "Di Luar RO" sites: AOI sitting outside the RO boundary.
function OutsideRoDiagram({ site }) {
  return (
    <svg viewBox="0 0 320 220" style={{ width: "100%", height: "auto", display: "block" }}>
      <rect x="0" y="0" width="320" height="220" fill="#3C4A34" />
      <rect x="0" y="0" width="320" height="220" fill="#000" opacity="0.08" />

      {/* stylised RO boundary */}
      <path d="M40 150 C 60 100, 140 90, 170 120 C 210 110, 250 130, 240 165 C 220 190, 100 195, 60 180 Z" fill="none" stroke="#D9B23C" strokeWidth="2" strokeDasharray="7 5" />
      {/* AOI kegiatan, sitting outside the boundary */}
      <rect x="220" y="30" width="60" height="50" fill="#7FA377" stroke="#4C6A47" strokeWidth="1.5" />

      <Callout x={150} y={20} dotX={250} dotY={55} text={`AOI ${site.ip}`} align="right" />
      <Callout x={20} y={195} dotX={90} dotY={165} text="Lokasi di luar RO" tone="danger" />
    </svg>
  );
}

function MechanismPanel({ site }) {
  if (site.status !== "Overlap Terdeteksi" && site.status !== "Di Luar RO") return null;
  return (
    <div style={{ marginTop: 16, paddingTop: 14, borderTop: "1px solid #D6D2C4" }}>
      <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 11.5, color: "#8A8677", marginBottom: 8 }}>
        Ilustrasi mekanisme (skematik, mengikuti Bab III Pedoman MRV)
      </div>
      {site.status === "Overlap Terdeteksi" ? <OverlapMechanismDiagram site={site} /> : <OutsideRoDiagram site={site} />}
    </div>
  );
}

function ProvinceBasemap({ highlightName }) {
  return (
    <g>
      {PROVINCES.map((p) => (
        <path
          key={p.n}
          d={p.d}
          fill={p.n === highlightName ? "#D7D9C4" : "#DCDCC9"}
          stroke="#C7C4AE"
          strokeWidth="0.6"
        />
      ))}
    </g>
  );
}

function SpatialView({ sites, selected, setSelected }) {
  return (
    <div style={{ display: "flex", gap: 0, alignItems: "stretch" }}>
      <div style={{ flex: "1 1 62%", border: "1px solid #D6D2C4", borderRight: "none", background: "#EAEBDF", position: "relative" }}>
        <div style={{ position: "absolute", top: 14, left: 18, fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12, color: "#5C5A4E" }}>
          Batas provinsi disederhanakan dari data GeoJSON &middot; luas AOI ditampilkan tidak berskala
        </div>
        <svg viewBox={`0 0 ${MAP_W} ${MAP_H}`} style={{ width: "100%", height: "auto", display: "block" }}>
          <ProvinceBasemap highlightName={selected?.provinsi} />

          {sites.map((s) => {
            const active = selected?.id === s.id;
            const hw = aoiHalfWidth(s.luas) * (active ? 1.25 : 1);
            const color = STATUS_META[s.status].color;
            const flagged = s.status === "Overlap Terdeteksi" || s.status === "Di Luar RO";
            return (
              <g key={s.id} onClick={() => setSelected(s)} style={{ cursor: "pointer" }}>
                {flagged && (
                  <polygon
                    points={squarePoints(s.cx, s.cy, hw * 1.5, -12)}
                    fill="none"
                    stroke={color}
                    strokeWidth="1"
                    strokeDasharray="2 2"
                  />
                )}
                <polygon
                  points={squarePoints(s.cx, s.cy, hw, 6)}
                  fill={color}
                  fillOpacity={active ? 0.55 : 0.35}
                  stroke={color}
                  strokeWidth={active ? 1.6 : 1}
                />
              </g>
            );
          })}
        </svg>

        <div style={{ display: "flex", gap: 16, flexWrap: "wrap", padding: "10px 18px 16px", borderTop: "1px solid #D6D2C4" }}>
          {Object.entries(STATUS_META).map(([label, meta]) => (
            <div key={label} style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12, color: "#5C5A4E" }}>
              <span style={{ width: 9, height: 9, background: meta.color, opacity: 0.6, border: `1px solid ${meta.color}`, display: "inline-block" }} />
              {label}
            </div>
          ))}
        </div>
      </div>

      <div style={{ flex: "1 1 38%", border: "1px solid #D6D2C4", padding: 22, background: "#F5F3EA", minHeight: 300, maxHeight: 640, overflowY: "auto" }}>
        {!selected ? (
          <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", color: "#5C5A4E", fontSize: 13.5, lineHeight: 1.6 }}>
            Klik salah satu AOI pada peta untuk melihat detail lokasi, status verifikasi, dan keterkaitan datanya dengan Rencana Operasional.
          </div>
        ) : (
          <div>
            <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 11.5, color: PMU_META[selected.pmu].color, marginBottom: 6 }}>
              {PMU_META[selected.pmu].label} &middot; {selected.provinsi}
            </div>
            <div style={{ fontFamily: "'Source Serif 4', serif", fontSize: 21, color: "#1B2A22", marginBottom: 10, lineHeight: 1.3 }}>
              {selected.name}
            </div>
            <StatusBadge status={selected.status} />

            <div style={{ marginTop: 18, display: "grid", gridTemplateColumns: "1fr 1fr", rowGap: 14, columnGap: 12 }}>
              <Field label="Implementing Partner" value={selected.ip} />
              <Field label="Jenis kegiatan" value={selected.kegiatan} />
              <Field label="Luas" value={`${fmt(selected.luas)} ha`} />
              <Field label="Jenis PCK" value={selected.jenisPck} />
              <Field label="Cadangan karbon" value={`${fmt(selected.pck)} tCO\u2082e`} />
              <Field label="Kode lokasi" value={selected.id} />
            </div>

            {selected.status === "Overlap Terdeteksi" && (
              <Note tone="danger">
                Terdeteksi irisan geometri dengan AOI {selected.overlapIp || "IP lain"}. Menunggu klarifikasi lapangan oleh PMU sebelum status ditetapkan TT MRV.
              </Note>
            )}
            {selected.status === "Di Luar RO" && (
              <Note tone="neutral">Lokasi berada di luar cakupan Rencana Operasional. Memerlukan justifikasi tertulis dan persetujuan OMO.</Note>
            )}
            {selected.status === "Perlu Klarifikasi" && (
              <Note tone="warn">Konsistensi data spasial dan capaian fisik belum sepenuhnya terverifikasi.</Note>
            )}

            <MechanismPanel site={selected} />
          </div>
        )}
      </div>
    </div>
  );
}

function CarbonView({ sites }) {
  const byPmuJenis = useMemo(() => {
    return Object.keys(PMU_META).map((pmu) => {
      const row = { pmu: PMU_META[pmu].label };
      Object.keys(JENIS_META).forEach((j) => {
        row[j] = sites.filter((s) => s.pmu === pmu && s.jenisPck === j).reduce((a, s) => a + s.pck, 0);
      });
      return row;
    });
  }, [sites]);

  const byJenisTotal = Object.keys(JENIS_META).map((j) => ({
    jenis: j,
    total: sites.filter((s) => s.jenisPck === j).reduce((a, s) => a + s.pck, 0),
  }));
  const grandTotal = byJenisTotal.reduce((a, r) => a + r.total, 0);

  return (
    <div>
      <div style={{ display: "flex", gap: 0, border: "1px solid #D6D2C4", borderBottom: "none" }}>
        {byJenisTotal.map((r, i) => {
          const Icon = JENIS_META[r.jenis].icon;
          const pct = grandTotal ? Math.round((r.total / grandTotal) * 100) : 0;
          return (
            <div key={r.jenis} style={{ flex: 1, padding: "18px 22px", borderLeft: i === 0 ? "none" : "1px solid #D6D2C4" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                <Icon size={16} color={JENIS_META[r.jenis].color} strokeWidth={2} />
                <span style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 13, color: "#5C5A4E" }}>PCK {r.jenis}</span>
              </div>
              <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontWeight: 600, fontSize: 24, color: "#1B2A22" }}>
                {fmt(r.total)}
                <span style={{ fontSize: 13, fontWeight: 400, color: "#5C5A4E", marginLeft: 6 }}>tCO\u2082e</span>
              </div>
              <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12, color: "#8A8677", marginTop: 3 }}>{pct}% dari total cadangan</div>
            </div>
          );
        })}
      </div>

      <div style={{ border: "1px solid #D6D2C4", padding: "20px 22px 10px" }}>
        <SectionTitle>Cadangan karbon per PMU, menurut jenis PCK</SectionTitle>
        <ResponsiveContainer width="100%" height={260}>
          <BarChart data={byPmuJenis} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="2 4" stroke="#D6D2C4" vertical={false} />
            <XAxis dataKey="pmu" tick={{ fontFamily: "IBM Plex Sans", fontSize: 12, fill: "#5C5A4E" }} axisLine={{ stroke: "#D6D2C4" }} tickLine={false} />
            <YAxis tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: "#5C5A4E" }} axisLine={false} tickLine={false} width={50} />
            <Tooltip contentStyle={{ fontFamily: "IBM Plex Sans", fontSize: 12.5, border: "1px solid #D6D2C4", borderRadius: 0 }} formatter={(v) => `${fmt(v)} tCO\u2082e`} />
            <Legend wrapperStyle={{ fontFamily: "IBM Plex Sans", fontSize: 12.5 }} />
            {Object.keys(JENIS_META).map((j) => (
              <Bar key={j} dataKey={j} stackId="a" fill={JENIS_META[j].color} radius={[0, 0, 0, 0]} />
            ))}
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div style={{ border: "1px solid #D6D2C4", borderTop: "none", padding: "20px 22px 10px" }}>
        <SectionTitle>Proyeksi menuju net sink 2030</SectionTitle>
        <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12.5, color: "#8A8677", marginTop: -8, marginBottom: 8 }}>
          Nilai negatif menunjukkan penyerapan bersih (juta tCO\u2082e). Target program: net sink \u2212140 juta tCO\u2082e pada 2030.
        </div>
        <ResponsiveContainer width="100%" height={240}>
          <LineChart data={TREND} margin={{ top: 8, right: 16, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="2 4" stroke="#D6D2C4" vertical={false} />
            <XAxis dataKey="tahun" tick={{ fontFamily: "IBM Plex Sans", fontSize: 12, fill: "#5C5A4E" }} axisLine={{ stroke: "#D6D2C4" }} tickLine={false} />
            <YAxis tick={{ fontFamily: "IBM Plex Sans", fontSize: 11, fill: "#5C5A4E" }} axisLine={false} tickLine={false} width={50} />
            <Tooltip contentStyle={{ fontFamily: "IBM Plex Sans", fontSize: 12.5, border: "1px solid #D6D2C4", borderRadius: 0 }} />
            <ReferenceLine y={0} stroke="#8A8677" />
            <Line type="monotone" dataKey="target" stroke="#8A8677" strokeDasharray="4 3" dot={false} name="Target program" strokeWidth={1.6} />
            <Line type="monotone" dataKey="capaian" stroke="#2C4A3A" dot={{ r: 3 }} name="Capaian terverifikasi" strokeWidth={2.2} />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div style={{ border: "1px solid #D6D2C4", borderTop: "none" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 13 }}>
          <thead>
            <tr style={{ borderBottom: "1px solid #D6D2C4" }}>
              {["Lokasi", "PMU", "IP", "Jenis PCK", "Luas (ha)", "Cadangan (tCO\u2082e)", "Status"].map((h) => (
                <th key={h} style={{ textAlign: "left", padding: "10px 16px", color: "#5C5A4E", fontWeight: 500, fontSize: 12 }}>
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {sites
              .slice()
              .sort((a, b) => b.pck - a.pck)
              .map((s) => (
                <tr key={s.id} style={{ borderBottom: "1px solid #E5E2D6" }}>
                  <td style={{ padding: "10px 16px", color: "#1B2A22" }}>{s.name}</td>
                  <td style={{ padding: "10px 16px", color: PMU_META[s.pmu].color }}>{s.pmu}</td>
                  <td style={{ padding: "10px 16px", color: "#5C5A4E" }}>{s.ip}</td>
                  <td style={{ padding: "10px 16px", color: "#5C5A4E" }}>{s.jenisPck}</td>
                  <td style={{ padding: "10px 16px", color: "#5C5A4E" }}>{fmt(s.luas)}</td>
                  <td style={{ padding: "10px 16px", color: "#1B2A22", fontWeight: 500 }}>{fmt(s.pck)}</td>
                  <td style={{ padding: "10px 16px" }}>
                    <StatusBadge status={s.status} />
                  </td>
                </tr>
              ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function EmissionKpiStrip({ year }) {
  const t = emissionTotalsForYear(year);
  const items = [
    { label: `Baseline emisi ${year}`, value: fmt1(t.baseline), unit: "juta tCO\u2082e" },
    { label: `Capaian aktual ${year}`, value: fmt1(t.aktual), unit: "juta tCO\u2082e" },
    { label: "Pengurangan emisi tercapai", value: fmt1(t.reduksi), unit: "juta tCO\u2082e", accent: true },
    { label: "% dari baseline", value: `${Math.round((t.reduksi / t.baseline) * 100)}%`, unit: "tereduksi" },
  ];
  return (
    <div style={{ display: "flex", flexWrap: "wrap", borderTop: "1px solid #D6D2C4", borderBottom: "1px solid #D6D2C4" }}>
      {items.map((it, i) => (
        <div key={it.label} style={{ flex: "1 1 180px", padding: "16px 22px", borderLeft: i === 0 ? "none" : "1px solid #D6D2C4" }}>
          <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 12.5, color: "#5C5A4E", marginBottom: 4 }}>{it.label}</div>
          <div style={{ fontFamily: "'IBM Plex Sans', sans-serif", fontWeight: 600, fontSize: 26, color: it.accent ? "#2C4A3A" : "#1B2A22", lineHeight: 1.1 }}>
            {it.value}
            <span style={{ fontSize: 13, fontWeight: 400, color: "#5C5A4E", marginLeft: 6 }}>{it.unit}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

function EmissionCategoryTable({ year }) {
  const rows = emissionRowsForYear(year);
  const totals = emissionTotalsForYear(year);
  return (
    <div style={{ border: "1px solid #D6D2C4" }}>
      <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: "'IBM Plex Sans', sans-serif", fontSize: 13 }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #D6D2C4" }}>
            {["Kategori", "Baseline (juta tCO\u2082e)", "Capaian aktual (juta tCO\u2082e)", "Pengurangan emisi (juta tCO\u2082e)"].map((h) => (
              <th key={h} style={{ textAlign: "left", padding: "10px 16px", color: "#5C5A4E", fontWeight: 500, fontSize: 12 }}>
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.key} style={{ borderBottom: "1px solid #E5E2D6" }}>
              <td style={{ padding: "10px 16px", color: "#1B2A22", display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ width: 9, height: 9, background: r.color, display: "inline-block", flex: "none" }} />
                {r.label}
              </td>
              <td style={{ padding: "10px 16px", color: "#5C5A4E" }}>{fmt1(r.baseline)}</td>
              <td style={{ padding: "10px 16px", color: "#5C5A4E" }}>{fmt1(r.aktual)}</td>
              <td style={{ padding: "10px 16px", color: "#2C4A3A", fontWeight: 500 }}>{fmt1(r.reduksi)}</td>
            </tr>
          ))}
          <tr>
            <td style={{ padding: "10px 16px", color: "#1B2A22", fontWeight: 600 }}>Total</td>
            <td style={{ padding: "10px 16px", color: "#1B2A22", fontWeight: 600 }}>{fmt1(totals.baseline)}</td>
            <td style={{ padding: "10px 16px", color: "#1B2A22", fontWeight: 600 }}>{fmt1(totals.aktual)}</td>
            <td style={{ padding: "10px 16px", color: "#2C4A3A", fontWeight: 600 }}>{fmt1(totals.reduksi)}</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

// --- Beranda (Homepage) -----------------------------------------------------
